import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-physics-mechanics-forces-newton-laws-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Weight vs. mass?`]: {
    question: r`A 4.0 kg specimen container hangs at rest from a spring scale that is marked in newtons (g = 10 m/s²). What does the scale read, and what is it measuring?`,
    options: [r`4.0 N, the gravitational force on the container`, r`40 N, the gravitational force on the container`, r`40 N, the amount of matter in the container`, r`4.0 N, the amount of matter in the container`],
    correctAnswer: 1,
    explanation: r`The scale responds to weight, W = mg = (4.0)(10) = 40 N, which is a force. The 4.0 N answers treat the mass value as if it were the weight, and the answers about the amount of matter describe mass, which is measured in kilograms and is not what a spring scale senses.`,
  },
  [r`How do you calculate friction force, and how do static and kinetic friction differ?`]: {
    question: r`A 10 kg crate rests on a level floor where μs = 0.5 and μk = 0.4 (g = 10 m/s²). A worker pushes horizontally on it with 30 N. What friction force acts on the crate?`,
    options: [r`50 N`, r`40 N`, r`30 N`, r`20 N`],
    correctAnswer: 2,
    explanation: r`The largest static friction available is μsN = (0.5)(100) = 50 N, so a 30 N push cannot move the crate and static friction simply matches it at 30 N. The 50 N answer treats the maximum as the actual value, 40 N is the kinetic value that applies only while sliding, and 20 N is the difference between the maximum and the push.`,
  },
  [r`State Newton's second law and what it says about net force and acceleration.`]: {
    question: r`A certain net force gives cart A an acceleration of 6 m/s² and gives cart B an acceleration of 3 m/s². The carts are fastened together and the same net force is applied. What is the acceleration of the pair?`,
    options: [r`9 m/s²`, r`4.5 m/s²`, r`3 m/s²`, r`2 m/s²`],
    correctAnswer: 3,
    explanation: r`From m = F/a the masses are F/6 and F/3, which add to F/2, so the same force gives a = 2 m/s². Adding the accelerations gives 9 m/s², averaging them gives 4.5 m/s², and 3 m/s² ignores cart A. The acceleration of the pair must be smaller than either cart's alone because the mass is larger.`,
  },
  [r`A 5 kg box is pushed across a floor with a coefficient of kinetic friction of 0.3. What is the frictional force? (g = 9.8 $m/s^{2}$)`]: {
    question: r`An 8.0 kg sled slides across level packed snow with a coefficient of kinetic friction of 0.25 (g = 10 m/s²). What is the friction force on the sled?`,
    options: [r`2.0 N`, r`80 N`, r`20 N`, r`32 N`],
    correctAnswer: 2,
    explanation: r`On level ground N = mg = 80 N, so fk = μkN = (0.25)(80) = 20 N. The 2.0 N answer multiplies μk by the mass and leaves out g, 80 N is the normal force itself, and 32 N divides the mass by the coefficient instead of multiplying the normal force by it.`,
  },
  [r`A 1000 kg car accelerates from 0 to 30 m/s in 6 seconds. What is the average net force?`]: {
    question: r`A 60 kg sprinter leaves the blocks and reaches 9.0 m/s in 1.5 s. What is the average net horizontal force on her during that time?`,
    options: [r`360 N`, r`540 N`, r`810 N`, r`90 N`],
    correctAnswer: 0,
    explanation: r`Her acceleration is Δv/Δt = 9.0/1.5 = 6.0 m/s², so F = ma = (60)(6.0) = 360 N. The 540 N answer multiplies mass by the final speed, 810 N multiplies mass, speed and time together, and 90 N multiplies mass by the time. Only mass times acceleration is a force.`,
  },
  [r`The SI unit of force is equivalent to:`]: {
    question: r`A student multiplies a fluid density in kg/m³ by an area in m² and by the square of a speed in m/s. The unit of the result is equivalent to which SI unit?`,
    options: [r`The joule (J)`, r`The pascal (Pa)`, r`The watt (W)`, r`The newton (N)`],
    correctAnswer: 3,
    explanation: r`(kg/m³)(m²)(m²/s²) = kg·m/s², which is the newton, so the product is a force. A joule is kg·m²/s², one more factor of length, a pascal is kg/(m·s²), a force per area, and a watt is kg·m²/s³, an energy per time.`,
  },
  [r`A 2 m beam has a 100 N weight 0.5 m from the pivot. Torque?`]: {
    question: r`A 3.0 m beam is hinged at its left end. A 60 N weight hangs from the beam 0.50 m from the hinge. What torque does the weight exert about the hinge?`,
    options: [r`30 N·m`, r`180 N·m`, r`150 N·m`, r`120 N·m`],
    correctAnswer: 0,
    explanation: r`Torque is the force times its distance from the pivot: (60 N)(0.50 m) = 30 N·m. The 180 N·m answer uses the full beam length, 150 N·m uses the distance to the far end of the beam, and 120 N·m divides the force by the distance. The length of the beam itself does not matter.`,
  },
  [r`Inertia depends on:`]: {
    question: r`Two sealed canisters of the same size float at rest inside an orbiting station. One is empty and one is packed with lead. An astronaut gives each the same brief push, and the lead-filled one moves away more slowly. Why?`,
    options: [r`It has more weight pressing it down`, r`It has more momentum before the push`, r`It has more volume, and so more drag`, r`It has more mass, and so more inertia`],
    correctAnswer: 3,
    explanation: r`Resistance to a change in motion is inertia, and inertia is set by mass alone, so the lead-filled canister gains less speed from the same push. Nothing presses the floating canisters down, both start at rest with zero momentum, and the canisters are the same size, so volume cannot explain the difference.`,
  },
  [r`A force applied at the pivot produces torque of:`]: {
    question: r`A seesaw pivots at its center. A 300 N child stands on the board directly over the pivot, and a 200 N child sits 1.5 m from the pivot. What is the magnitude of the net torque about the pivot from the two children?`,
    options: [r`300 N·m`, r`750 N·m`, r`150 N·m`, r`0 N·m`],
    correctAnswer: 0,
    explanation: r`The child over the pivot has a lever arm of zero and produces no torque, so the net torque is (200 N)(1.5 m) = 300 N·m. The 750 N·m answer puts both weights at 1.5 m, 150 N·m subtracts the weights first and then uses 1.5 m, and 0 N·m assumes the heavier child balances the board.`,
  },
  [r`A 10 kg block on a frictionless surface feels 50 N. Acceleration?`]: {
    question: r`A 2.0 kg block rests on a frictionless horizontal table and is pulled horizontally with a force of 8.0 N (g = 10 m/s²). What is its acceleration?`,
    options: [r`16 m/s²`, r`4.0 m/s²`, r`0.25 m/s²`, r`14 m/s²`],
    correctAnswer: 1,
    explanation: r`The only horizontal force is the 8.0 N pull, so a = F/m = 8.0/2.0 = 4.0 m/s². The 16 m/s² answer multiplies force by mass, 0.25 m/s² divides mass by force, and 14 m/s² adds g, even though gravity is vertical and is cancelled by the normal force.`,
  },
  [r`A system is in translational equilibrium when:`]: {
    question: r`Which of these objects is in translational equilibrium at the moment described?`,
    options: [r`A crate sliding in a straight line at a steady 3 m/s`, r`A ball at the top of its flight, momentarily at rest`, r`A car rounding a level curve at a steady 20 m/s`, r`A stone at the instant it is released from rest`],
    correctAnswer: 0,
    explanation: r`Translational equilibrium means zero net force, which means zero acceleration, and the crate moving at constant velocity satisfies that. The ball at its peak and the stone just released are at rest for an instant but still accelerate downward under gravity, and the car on the curve has an inward acceleration because its direction is changing.`,
  },
  [r`At what incline angle does a block just begin to slide?`]: {
    question: r`A wooden block sits on a board that is tilted slowly upward. The block starts to slide when the board reaches 30° (sin 30° = 0.50, cos 30° ≈ 0.87, tan 30° ≈ 0.58). What is the coefficient of static friction between block and board?`,
    options: [r`0.50`, r`0.58`, r`0.87`, r`1.7`],
    correctAnswer: 1,
    explanation: r`At the point of slipping mg sin θ = μs mg cos θ, so μs = tan θ ≈ 0.58. The 0.50 answer uses sin θ, 0.87 uses cos θ, and 1.7 is cos θ divided by sin θ, the ratio upside down.`,
  },
  [r`What must be excluded from a correct free-body diagram?`]: {
    question: r`A box is sliding to a stop on a rough level floor. A student's free-body diagram of the box shows its weight, the normal force, kinetic friction pointing backward, and a forward arrow labelled "force of motion". Which arrow should be erased?`,
    options: [r`The friction arrow, since the box is still moving`, r`The normal arrow, since the floor is horizontal`, r`The weight arrow, since the box is not falling`, r`The forward arrow, since velocity is not a force`],
    correctAnswer: 3,
    explanation: r`Nothing is pushing the box forward: it keeps moving because of its inertia, and a velocity or momentum arrow does not belong among the forces. Kinetic friction is a real force that acts exactly because the box is sliding, the floor still pushes up on the box, and gravity acts whether or not the box falls.`,
  },
  [r`How do mass and weight differ for an astronaut on the Moon?`]: {
    question: r`On the Moon, where g is about one-sixth of its value on Earth, an astronaut pushes horizontally on an equipment cart with frictionless wheels and later holds the cart up off the ground. How do these compare with doing the same on Earth?`,
    options: [r`Six times the acceleration for the same push; one-sixth the force to hold it up`, r`Same acceleration for the same push; the same force to hold it up`, r`Same acceleration for the same push; one-sixth the force to hold it up`, r`Six times the acceleration for the same push; the same force to hold it up`],
    correctAnswer: 2,
    explanation: r`The cart's mass, and so its inertia, is unchanged, so the same horizontal push gives the same acceleration. Its weight mg is one-sixth as large, so holding it up takes one-sixth the force. Six times the acceleration confuses weight with inertia, and the same holding force forgets that weight depends on g.`,
  },
  [r`A scale under a patient in an elevator moving upward at constant velocity reads {{c1::$mg$}}.`]: {
    question: r`A 60 kg patient stands on a scale in an elevator that is rising at a steady 3.0 m/s (g = 10 m/s²). What does the scale read?`,
    options: [r`780 N`, r`420 N`, r`180 N`, r`600 N`],
    correctAnswer: 3,
    explanation: r`At constant velocity the acceleration is zero, so the normal force equals the true weight, (60)(10) = 600 N. The 780 N and 420 N answers add or subtract the speed as if it were an acceleration, and 180 N multiplies mass by speed. Only acceleration changes a scale reading.`,
  },
  [r`Two blocks in contact are pushed across a table by force $F$. How do you find the contact force between them?`]: {
    question: r`A 30 N horizontal force pushes on a 4.0 kg block, which is in contact with a 2.0 kg block in front of it. Both slide together on a frictionless surface. What force does the 4.0 kg block exert on the 2.0 kg block?`,
    options: [r`30 N`, r`10 N`, r`20 N`, r`15 N`],
    correctAnswer: 1,
    explanation: r`The pair accelerates at a = 30/(4.0 + 2.0) = 5.0 m/s², and the contact force is the only horizontal force on the front block, so it equals (2.0)(5.0) = 10 N. The 30 N answer passes the whole push through unchanged, 20 N is the net force on the rear block, and 15 N splits the push evenly without regard to mass.`,
  },
  [r`On a frictionless banked curve the design speed satisfies {{c1::$\tan\theta = v^2/(rg)$}}.`]: {
    question: r`A frictionless banked ramp of radius 80 m is to be designed for cars travelling at 20 m/s (g = 10 m/s²). What must tan θ of the banking angle be?`,
    options: [r`0.50`, r`2.0`, r`0.025`, r`0.25`],
    correctAnswer: 0,
    explanation: r`The design condition is tan θ = v²/(rg) = 400/(80 × 10) = 0.50. The 2.0 answer inverts the ratio, 0.025 forgets to square the speed, and 0.25 is v/r with g left out.`,
  },
  [r`Whiplash in a rear-end collision is a demonstration of {{c1::Newton's first law}}.`]: {
    question: r`In a frontal crash test the car stops abruptly, and an unbelted dummy keeps moving forward at the car's original speed until it reaches the dashboard. Which law does this show, and why?`,
    options: [r`The first law: no net force acts on the dummy to change its motion`, r`The first law: a forward force of inertia drives the dummy onward`, r`The second law: the dummy's mass gives it a large forward force`, r`The third law: the car's stopping force is passed on to the dummy`],
    correctAnswer: 0,
    explanation: r`With no belt, almost no horizontal force acts on the dummy, so it keeps its velocity while the car stops around it, which is Newton's first law. Inertia is not a force and nothing pushes the dummy forward, mass does not create a force by itself, and the third law pairs forces between two objects without explaining why the dummy keeps moving.`,
  },
  [r`In limb traction, how is the net therapeutic force found from two angled cables?`]: {
    question: r`Two traction cables pull on a patient's leg. Each has a tension of 100 N, and they are angled 60° to either side of the leg's long axis (cos 60° = 0.50, sin 60° ≈ 0.87). What is the net force along the axis of the leg?`,
    options: [r`200 N`, r`173 N`, r`100 N`, r`50 N`],
    correctAnswer: 2,
    explanation: r`The sideways components cancel by symmetry and the along-axis components add: 2(100)(cos 60°) = 100 N. The 200 N answer adds the tensions as if both pulled straight along the axis, 173 N uses the sine, which gives the cancelling sideways components, and 50 N is the contribution of one cable only.`,
  },
  [r`A centrifuge separates blood because denser particles require {{c1::more centripetal force}} than the plasma can supply.`]: {
    question: r`Two particles of equal volume sit at the same radius in a spinning centrifuge tube. Particle A has twice the mass of particle B. To stay on a circle of that radius, the inward force needed by A is:`,
    options: [r`Half the force needed by B`, r`Twice the force needed by B`, r`Equal to the force needed by B`, r`Four times the force needed by B`],
    correctAnswer: 1,
    explanation: r`At the same radius and rotation rate the centripetal force needed is proportional to mass, so A needs twice as much. When the surrounding fluid cannot supply it, the denser particle drifts outward. Half inverts the relationship, equal ignores mass, and four times squares a quantity that enters only to the first power.`,
  },
  [r`For a rope with significant mass, tension is greatest {{c1::at the end being pulled}}.`]: {
    question: r`A uniform 4.0 kg chain is used to drag a 6.0 kg block across frictionless ice. The free end of the chain is pulled horizontally with 20 N. What is the tension in the chain where it attaches to the block?`,
    options: [r`12 N`, r`20 N`, r`8.0 N`, r`16 N`],
    correctAnswer: 0,
    explanation: r`The system accelerates at 20/(4.0 + 6.0) = 2.0 m/s², and the link at the block must accelerate only the block, so the tension there is (6.0)(2.0) = 12 N. The 20 N answer assumes a massless chain with uniform tension, 8.0 N is the net force on the chain itself, and 16 N is the tension at the middle of the chain.`,
  },
  [r`Mass $m_1$ on a table with friction is pulled by a hanging mass $m_2$. What is the acceleration?`]: {
    question: r`A 6.0 kg block on a table (μk = 0.50) is tied by a light string over an ideal pulley to a hanging 4.0 kg mass, and the system is moving with the hanging mass descending (g = 10 m/s²). What is the acceleration?`,
    options: [r`4.0 m/s²`, r`2.5 m/s²`, r`7.0 m/s²`, r`1.0 m/s²`],
    correctAnswer: 3,
    explanation: r`The driving force is m₂g = 40 N, kinetic friction on the block is (0.50)(60) = 30 N, and the total mass is 10 kg, so a = (40 − 30)/10 = 1.0 m/s². The 4.0 m/s² answer leaves out friction, 2.5 m/s² divides by the hanging mass alone, and 7.0 m/s² adds friction to the driving force.`,
  },
  [r`What is true of tension throughout an ideal massless rope over a frictionless pulley?`]: {
    question: r`A light rope passes over two frictionless pulleys, with an 8.0 kg mass hanging at rest from each end (g = 10 m/s²). A spring scale is spliced into the horizontal section of rope between the pulleys. What does it read?`,
    options: [r`160 N`, r`0 N`, r`80 N`, r`40 N`],
    correctAnswer: 2,
    explanation: r`Tension in an ideal rope is the same everywhere, and each hanging mass at rest requires T = mg = 80 N, so the scale reads 80 N. The 160 N answer adds the two weights, 0 N assumes the equal pulls cancel inside the rope, and 40 N splits one weight between the two sides.`,
  },
  [r`What sets the maximum speed of a car rounding a flat curve of radius $r$?`]: {
    question: r`A car approaches a flat curve of radius 100 m on a road where μs = 0.40 (g = 10 m/s²). What is the greatest speed at which it can round the curve without skidding?`,
    options: [r`50 m/s`, r`400 m/s`, r`20 m/s`, r`6.3 m/s`],
    correctAnswer: 2,
    explanation: r`Static friction supplies the centripetal force, so v = √(μs g r) = √(0.40 × 10 × 100) = √400 = 20 m/s. The 50 m/s answer divides by μs inside the root, 400 m/s forgets the square root, and 6.3 m/s leaves g out.`,
  },
  [r`The normal force on a book and the book's weight are {{c1::not a Newton's third-law pair}}.`]: {
    question: r`A 2.0 kg book rests on a table in an elevator that is accelerating upward at 2.0 m/s² (g = 10 m/s²). What are the normal force on the book and the force the book exerts on the table?`,
    options: [r`24 N on the book and 24 N on the table`, r`24 N on the book and 20 N on the table`, r`20 N on the book and 20 N on the table`, r`20 N on the book and 24 N on the table`],
    correctAnswer: 0,
    explanation: r`The second law gives N = m(g + a) = (2.0)(12) = 24 N, and its third-law partner, the book's push on the table, is also 24 N. The answers with 20 N use the weight, but the weight is not the partner of the normal force and need not equal it. Here the weight stays 20 N while both contact forces are 24 N.`,
  },
  [r`What features must a Newton's third-law force pair share?`]: {
    question: r`An apple that weighs 1 N hangs at rest from its stem. What is the Newton's third-law partner of the apple's weight?`,
    options: [r`The 1 N tension force of the stem on the apple, acting upward`, r`The 1 N pull of the apple on its own stem, acting downward`, r`A far weaker gravitational pull of the apple on Earth, upward`, r`The 1 N gravitational pull of the apple on Earth, acting upward`],
    correctAnswer: 3,
    explanation: r`The weight is Earth's gravitational pull on the apple, so its partner is the apple's gravitational pull on Earth: same type, same size, opposite direction, on the other object. The stem's tension balances the weight but acts on the same object and is a different type of force, the apple's pull on the stem is the partner of that tension, and a pair is never unequal.`,
  },
  [r`Does zero net force mean an object is at rest?`]: {
    question: r`A car travels along a straight, level highway at a steady 30 m/s while its tires provide a forward drive force of 800 N. What is the total resistive force (air drag plus rolling resistance) on the car?`,
    options: [r`Less than 800 N, because the car moves forward`, r`800 N, because the net force must be zero`, r`0 N, because steady motion requires no force`, r`More than 800 N, because drag grows with speed`],
    correctAnswer: 1,
    explanation: r`Constant velocity means zero acceleration and so zero net force, which requires the resistive forces to total exactly 800 N. A resistive force below 800 N would make the car speed up and one above 800 N would slow it down. Zero resistance with an 800 N drive force would also leave a net force and an acceleration.`,
  },
  [r`An object in uniform circular motion has constant speed but {{c1::nonzero acceleration}}.`]: {
    question: r`A car circles a track of radius 50 m at a steady 10 m/s. What is its acceleration?`,
    options: [r`2 m/s², directed toward the center of the track`, r`2 m/s², directed along its direction of travel`, r`0 m/s², because the speed of the car is constant`, r`5 m/s², directed toward the center of the track`],
    correctAnswer: 0,
    explanation: r`The direction of the velocity keeps changing, so there is an acceleration v²/r = 100/50 = 2 m/s² pointing at the center. An acceleration along the direction of travel would change the speed, zero acceleration confuses constant speed with constant velocity, and 5 m/s² divides the radius by the speed.`,
  },
  [r`What defines terminal velocity, and what is the acceleration there?`]: {
    question: r`A skydiver falling at a terminal speed of 50 m/s opens her parachute, and at that instant the drag on her becomes much larger than her weight. What happens next?`,
    options: [r`She slows until the drag falls back to equal her weight`, r`She slows steadily until she comes to rest in the air`, r`She keeps her speed, since drag can never exceed weight`, r`She moves upward, since the net force now points upward`],
    correctAnswer: 0,
    explanation: r`The net upward force slows her, and drag drops as speed drops until it balances her weight again at a new, lower terminal speed with zero acceleration. She cannot come to rest, because drag would vanish before then and gravity would speed her up. Drag can exceed weight for a while, and an upward net force changes the velocity gradually and does not reverse it at once.`,
  },
  [r`As an incline gets steeper, the friction force available {{c1::decreases}}.`]: {
    question: r`A 10 kg block rests on a ramp where μs = 0.50 (g = 10 m/s²). The ramp is raised from 37° to 53° (cos 37° = sin 53° ≈ 0.80, sin 37° = cos 53° ≈ 0.60). How does the maximum static friction available change?`,
    options: [r`It rises from 30 N to 40 N`, r`It stays at 50 N throughout`, r`It rises from 60 N to 80 N`, r`It falls from 40 N to 30 N`],
    correctAnswer: 3,
    explanation: r`Maximum static friction is μs mg cos θ: (0.50)(100)(0.80) = 40 N at 37° and (0.50)(100)(0.60) = 30 N at 53°. The rise from 30 N to 40 N uses the sine in place of the cosine, the constant 50 N uses N = mg as on level ground, and 60 N to 80 N is the downhill weight component, not friction.`,
  },
  [r`Atwood machine acceleration is {{c1::$a = (m_1 - m_2)g/(m_1 + m_2)$}}.`]: {
    question: r`To slow a fall enough to time it by hand, a student joins a 2.2 kg cylinder and a 1.8 kg cylinder with a light thread over an ideal pulley and lets go (g = 10 m/s²). How quickly does the heavier cylinder gain speed?`,
    options: [r`4.0 m/s²`, r`1.0 m/s²`, r`1.8 m/s²`, r`10 m/s²`],
    correctAnswer: 1,
    explanation: r`The weight difference drives the total mass: a = (2.2 − 1.8)(10)/(2.2 + 1.8) = 4.0/4.0 = 1.0 m/s². The 4.0 m/s² answer is the 4.0 N weight difference with no division by mass, 1.8 m/s² divides that difference by the heavier cylinder alone, and 10 m/s² treats the heavier cylinder as if it were in free fall.`,
  },
  [r`Why does pulling a suitcase by a handle angled upward reduce friction?`]: {
    question: r`A 20 kg suitcase is dragged along a level floor by a strap that pulls with 50 N at 53° above the horizontal (sin 53° ≈ 0.80, cos 53° ≈ 0.60). With μk = 0.25 and g = 10 m/s², what is the kinetic friction force?`,
    options: [r`40 N`, r`50 N`, r`60 N`, r`42.5 N`],
    correctAnswer: 0,
    explanation: r`The strap's upward component is (50)(0.80) = 40 N, so N = 200 − 40 = 160 N and fk = (0.25)(160) = 40 N. The 50 N answer uses N = mg and ignores the strap, 60 N adds the vertical component as if the strap pushed down, and 42.5 N subtracts the horizontal component in place of the vertical one.`,
  },
  [r`Is acceleration always in the direction of motion?`]: {
    question: r`A ball is thrown straight up and air resistance is negligible (g = 10 m/s²). What is its acceleration at the very top of its flight, where its velocity is zero?`,
    options: [r`Zero, because the ball is momentarily at rest`, r`10 m/s² upward, because it is about to reverse`, r`Zero, because the forces balance at the peak`, r`10 m/s² downward, the same as on the way up`],
    correctAnswer: 3,
    explanation: r`Gravity is the only force throughout, so the acceleration is 10 m/s² downward on the way up, at the top, and on the way down. Zero velocity does not mean zero acceleration, no forces balance at the peak because only gravity acts, and an upward acceleration would need an upward net force that does not exist.`,
  },
  [r`What external force propels a walking person forward?`]: {
    question: r`A sprinter drives out of the starting position on a level track. Which force is the external horizontal force that accelerates her forward?`,
    options: [r`Static friction from her shoe on the track, directed backward`, r`Kinetic friction from the track on her shoe, directed forward`, r`The force of her leg muscles on her own body, directed forward`, r`Static friction from the track on her shoe, directed forward`],
    correctAnswer: 3,
    explanation: r`Her shoe pushes backward on the track without slipping, and the track's static friction pushes forward on her; that is the only external horizontal force on her. The backward friction acts on the track, not on her, kinetic friction would mean the shoe is slipping, and muscle forces are internal and cannot accelerate her center of mass.`,
  },
  [r`The normal force does {{c1::zero}} work on a block sliding down an incline.`]: {
    question: r`A 20 kg child travels 4.0 m along a straight, frictionless playground slide, dropping 2.0 m in height, while the slide surface pushes on the child with a normal force of 170 N (g = 10 m/s²). How much work does that normal force do on the child?`,
    options: [r`680 J`, r`0 J`, r`400 J`, r`−680 J`],
    correctAnswer: 1,
    explanation: r`The normal force is perpendicular to the displacement along the slide, so W = Fd cos 90° = 0. Both 680 J answers multiply 170 N by 4.0 m as if the force lay along the motion, and 400 J is the work done by gravity, mg times the 2.0 m drop in height.`,
  },
  [r`A sign hangs from two ropes. What happens to the tension as the ropes are pulled closer to horizontal?`]: {
    question: r`A 100 N sign hangs from two symmetric ropes. The ropes are tightened so that each makes 10° with the horizontal (sin 10° ≈ 0.17) where it used to make 30° (sin 30° = 0.50). What has happened to the tension in each rope?`,
    options: [r`It has fallen from 100 N to about 34 N`, r`It has stayed at 50 N, half the weight`, r`It has fallen from 290 N to about 100 N`, r`It has risen from 100 N to about 290 N`],
    correctAnswer: 3,
    explanation: r`Only vertical components hold the sign, so 2T sin θ = 100 N: T = 100 N at 30° and T = 100/(0.34) ≈ 290 N at 10°. A fall to 34 N multiplies by the sine where it should divide, 50 N per rope is right only for vertical ropes, and the fall from 290 N swaps the two angles.`,
  },
  [r`In the standard friction model, friction is independent of which two variables?`]: {
    question: r`A crate sliding across a level floor at 2 m/s feels 40 N of kinetic friction. In the standard friction model, what is the friction force when it slides at 4 m/s, and when a second identical crate is stacked on top of it?`,
    options: [r`40 N at 4 m/s, and 80 N with the second crate`, r`80 N at 4 m/s, and 80 N with the second crate`, r`40 N at 4 m/s, and 40 N with the second crate`, r`80 N at 4 m/s, and 40 N with the second crate`],
    correctAnswer: 0,
    explanation: r`Kinetic friction is μkN: it does not depend on sliding speed, so it stays 40 N at 4 m/s, but stacking a second crate doubles the normal force and so doubles friction to 80 N. Answers with 80 N at 4 m/s make friction grow with speed, and answers with 40 N for the stack ignore the larger normal force.`,
  },
  [r`A patient stands on a scale in an elevator accelerating upward at $a$. The scale reads {{c1::$N = m(g + a)$}}.`]: {
    question: r`A hospital lift leaves the ground floor carrying a 50 kg patient who is standing on a floor scale. While the lift gains upward speed at 3.0 m/s² (g = 10 m/s²), what force does the scale show?`,
    options: [r`350 N`, r`650 N`, r`500 N`, r`150 N`],
    correctAnswer: 1,
    explanation: r`N − mg = ma, so N = m(g + a) = (50)(13) = 650 N. The 350 N answer subtracts the acceleration, which fits a downward acceleration, 500 N is the true weight and applies only at constant velocity, and 150 N is ma alone, the net force and not the scale reading.`,
  },
  [r`On an incline of angle $\theta$, weight resolves into which two components?`]: {
    question: r`A 20 kg cart is held at rest on a frictionless 30° ramp by a rope parallel to the ramp (g = 10 m/s², sin 30° = 0.50, cos 30° ≈ 0.87). What are the rope tension and the normal force?`,
    options: [r`Tension 174 N and normal force 100 N`, r`Tension 100 N and normal force 200 N`, r`Tension 100 N and normal force 174 N`, r`Tension 200 N and normal force 174 N`],
    correctAnswer: 2,
    explanation: r`The rope balances the downhill component, mg sin θ = (200)(0.50) = 100 N, and the surface balances the perpendicular component, mg cos θ = (200)(0.87) = 174 N. Swapping the values swaps sine and cosine, a 200 N normal force is the level-ground value, and a 200 N tension would be needed only to hang the cart vertically.`,
  },
  [r`Why do two blocks of different mass slide down a frictionless incline together?`]: {
    question: r`A 2.0 kg block released on a frictionless 30° incline accelerates at 5.0 m/s². An 8.0 kg block is released on the same incline. What is its acceleration?`,
    options: [r`20 m/s², because its weight is four times greater`, r`5.0 m/s², because mass cancels out of a = g sin θ`, r`1.25 m/s², because its inertia is four times greater`, r`10 m/s², because heavy objects fall at the full g`],
    correctAnswer: 1,
    explanation: r`The downhill force mg sin θ and the inertia m both scale with mass, so a = g sin θ = 5.0 m/s² for any block. The 20 m/s² answer counts the larger weight but not the larger inertia, 1.25 m/s² counts the inertia but not the weight, and 10 m/s² applies only to free fall, not to motion along a 30° slope.`,
  },
  [r`Apparent weight of a person in a freely falling elevator is {{c1::zero}}.`]: {
    question: r`A 70 kg test engineer stands on a scale inside a drop-tower capsule that is released into free fall (g = 10 m/s²). What does the scale read during the fall?`,
    options: [r`0 N, because gravity stops acting during free fall`, r`700 N, because her weight is unchanged in free fall`, r`1400 N, because the falling floor adds to her weight`, r`0 N, although gravity still pulls on her with 700 N`],
    correctAnswer: 3,
    explanation: r`With a = g downward, N = m(g − a) = 0: she and the scale fall together, so no contact force is needed, yet gravity still pulls with 700 N and is what makes her accelerate. Gravity does not switch off, a 700 N reading confuses true weight with the normal force a scale measures, and 1400 N adds g where it should be subtracted.`,
  },
  [r`When does the normal force on a horizontal floor NOT equal $mg$?`]: {
    question: r`A 5.0 kg box rests on a level floor while a hand presses straight down on it with 20 N (g = 10 m/s²). What is the normal force from the floor on the box?`,
    options: [r`70 N`, r`50 N`, r`30 N`, r`20 N`],
    correctAnswer: 0,
    explanation: r`The box is at rest, so the upward normal force must balance both downward forces: N = mg + 20 = 50 + 20 = 70 N. The 50 N answer assumes N always equals mg, 30 N subtracts the push as if the hand lifted the box, and 20 N counts only the hand's push.`,
  },
  [r`An object lurches forward the instant it breaks free because {{c1::$\mu_k < \mu_s$}}.`]: {
    question: r`A stuck 1.5 kg drawer breaks free when the horizontal pull on it reaches 12 N. The pull stays at 12 N, and the kinetic friction on the sliding drawer is 9.0 N. What is the drawer's acceleration just after it breaks free?`,
    options: [r`8.0 m/s²`, r`6.0 m/s²`, r`2.0 m/s²`, r`0 m/s²`],
    correctAnswer: 2,
    explanation: r`Once sliding starts, friction drops from its 12 N static maximum to 9.0 N, leaving a net force of 3.0 N and a = 3.0/1.5 = 2.0 m/s². The 8.0 m/s² answer ignores friction, 6.0 m/s² divides the friction force by the mass, and 0 m/s² assumes friction still equals the pull as it did before the drawer moved.`,
  },
  [r`A block just begins to slide on an incline when {{c1::$\tan\theta = \mu_s$}}.`]: {
    question: r`A 1.0 kg rubber block on a tilting board begins to slide when the board reaches 35°. A 4.0 kg block of the same rubber is placed on the same board. At what angle does it begin to slide?`,
    options: [r`Near 9°, because its weight is four times greater`, r`At 35°, because mass cancels from tan θ = μs`, r`Near 70°, because its normal force is much greater`, r`Never, because its friction limit is four times greater`],
    correctAnswer: 1,
    explanation: r`Slipping begins when mg sin θ = μs mg cos θ, so tan θ = μs with no mass in it, and both blocks slip at 35°. A smaller angle counts the larger downhill pull but not the larger friction, and a larger angle or no slipping counts the larger friction but not the larger downhill pull. The two grow in the same proportion.`,
  },
  [r`Why is $f_s = \mu_s N$ wrong as a general statement?`]: {
    question: r`A 5.0 kg book lies at rest on a level table where μs = 0.40 (g = 10 m/s²). No horizontal force is applied to it. What is the static friction force on the book?`,
    options: [r`20 N`, r`50 N`, r`0 N`, r`2.0 N`],
    correctAnswer: 2,
    explanation: r`Static friction only matches whatever force tries to slide the book, and nothing does here, so it is zero. The 20 N answer is μsN, which is the maximum available and is reached only at the point of slipping, 50 N is the normal force, and 2.0 N multiplies the coefficient by the mass.`,
  },
  [r`Centripetal force is {{c1::not a separate force}}; it is the net inward component of real forces.`]: {
    question: r`A car rounds a flat, level curve at constant speed without skidding. Which list gives every force on a correct free-body diagram of the car?`,
    options: [r`Weight, normal force, friction, and a centripetal force inward`, r`Weight, normal force, and static friction pointing inward`, r`Weight, normal force, and a centrifugal force pointing outward`, r`Weight, normal force, and kinetic friction pointing backward`],
    correctAnswer: 1,
    explanation: r`Static friction toward the center is the real force that supplies the needed centripetal force, alongside weight and the normal force. Adding a separate centripetal arrow counts that friction twice, a centrifugal force is not a real force on the car, and kinetic friction pointing backward describes a skid that slows the car, not a steady turn.`,
  },
  [r`Minimum speed to keep contact at the top of a vertical circle is the square root of {{c1::$gr$}}.`]: {
    question: r`A bucket of water is swung in a vertical circle of radius 0.90 m (g = 10 m/s²). What is the lowest speed at the top of the circle for which the water stays in the bucket?`,
    options: [r`9.0 m/s`, r`4.2 m/s`, r`3.0 m/s`, r`0.95 m/s`],
    correctAnswer: 2,
    explanation: r`At the critical speed gravity alone supplies the centripetal force, so mg = mv²/r and v = √(gr) = √9.0 = 3.0 m/s. The 9.0 m/s answer forgets the square root, 4.2 m/s uses √(2gr), and 0.95 m/s takes the root of the radius without g.`,
  },
  [r`Why does a rider feel heaviest at the bottom of a loop?`]: {
    question: r`An 80 kg pilot pulls out of a dive along a circular arc of radius 400 m, passing the lowest point at 100 m/s (g = 10 m/s²). What force does the seat exert on him there?`,
    options: [r`2000 N`, r`2800 N`, r`1200 N`, r`800 N`],
    correctAnswer: 1,
    explanation: r`At the bottom N − mg = mv²/r, and v²/r = 10 000/400 = 25 m/s², so N = (80)(10 + 25) = 2800 N. The 2000 N answer is the centripetal force alone, 1200 N subtracts the weight as would apply at the top of a loop, and 800 N is his weight, which the seat supplies only when he is not accelerating.`,
  },
  [r`A plot of friction force versus applied force rises along $y = x$, peaks, drops slightly, then flattens. Explain each region.`]: {
    question: r`A block weighing 50 N sits on a level surface. A plot of friction force against applied horizontal force rises along a line of slope 1 to a peak of 20 N, then drops and stays flat at 15 N. What are the coefficients of friction?`,
    options: [r`μs = 0.30 and μk = 0.40`, r`μs = 2.5 and μk = 3.3`, r`μs = 0.40 and μk = 0.30`, r`μs = 1.0 and μk = 0.75`],
    correctAnswer: 2,
    explanation: r`The peak is the maximum static friction, μsN = 20 N, and the flat part is kinetic friction, μkN = 15 N; with N = 50 N these give 0.40 and 0.30. Swapping them assigns the flat region to static friction, 2.5 and 3.3 divide N by the friction forces, and 1.0 and 0.75 take the slope of the rising line as the static coefficient.`,
  },
  [r`A car's maximum acceleration on level ground is {{c1::$\mu_s g$}}, independent of {{c1::its mass}}.`]: {
    question: r`A car's tires have μs = 0.80 on a level road (g = 10 m/s²). What is its greatest possible acceleration when its total mass is 1000 kg, and when it is loaded to 1500 kg?`,
    options: [r`8.0 m/s² empty and 5.3 m/s² loaded`, r`8.0 m/s² empty and 12 m/s² loaded`, r`8.0 m/s² empty and 8.0 m/s² loaded`, r`10 m/s² empty and 10 m/s² loaded`],
    correctAnswer: 2,
    explanation: r`Maximum grip is μs mg, so the greatest acceleration is μs g = 8.0 m/s² whatever the mass. The 5.3 m/s² answer keeps the grip fixed while the mass rises, 12 m/s² raises the grip without raising the inertia, and 10 m/s² leaves out the coefficient.`,
  },
  [r`In an elevator accelerating downward at $a$, a hanging mass has rope tension {{c1::$m(g - a)$}}.`]: {
    question: r`A 2.0 kg fluid bag hangs by a cord from the ceiling of an elevator that is accelerating downward at 3.0 m/s² (g = 10 m/s²). What is the tension in the cord?`,
    options: [r`26 N`, r`14 N`, r`20 N`, r`6.0 N`],
    correctAnswer: 1,
    explanation: r`Taking down as positive, mg − T = ma, so T = m(g − a) = (2.0)(7.0) = 14 N. The 26 N answer adds the acceleration, which fits an upward acceleration, 20 N is the weight and applies at constant velocity, and 6.0 N is ma alone, the net force on the bag.`,
  },
  [r`Two ropes at 60 degrees from vertical hold a 20 kg sign. Estimate the tension in each rope.`]: {
    question: r`A 16 kg surgical lamp hangs at rest from two ropes, each making 37° with the vertical (cos 37° ≈ 0.80, sin 37° ≈ 0.60, g = 10 m/s²). What is the tension in each rope?`,
    options: [r`80 N`, r`133 N`, r`100 N`, r`200 N`],
    correctAnswer: 2,
    explanation: r`The vertical components carry the 160 N weight: 2T cos 37° = 160 N, so T = 160/1.6 = 100 N. The 80 N answer simply halves the weight as if the ropes were vertical, 133 N uses the sine in place of the cosine, and 200 N has a single rope carry the whole weight.`,
  },
  [r`Estimate the friction force acting on a 1000 kg car during a 0.5 g emergency stop.`]: {
    question: r`A 1500 kg car makes an emergency stop on a level road, slowing at 0.80 g (g = 10 m/s²). What friction force does the road exert on it, and what coefficient of friction does that require?`,
    options: [r`12,000 N, which requires μ of about 1.25`, r`1200 N, which requires μ of about 0.080`, r`12,000 N, which requires μ of about 0.80`, r`15,000 N, which requires μ of about 1.0`],
    correctAnswer: 2,
    explanation: r`F = ma = (1500)(8.0) = 12,000 N, and μ = F/N = 12,000/15,000 = 0.80, a reasonable value for tires on dry pavement. A coefficient of 1.25 inverts that ratio, 1200 N uses 0.80 m/s² and not 0.80 g, and 15,000 N is the car's weight, which friction would equal only for a 1 g stop.`,
  },
  [r`A rope pulls a sled carrying a child. What force actually accelerates the child?`]: {
    question: r`A nurse pushes a supply cart so that it accelerates forward at 2.0 m/s². A 0.50 kg cup rides on the cart's flat top without slipping (g = 10 m/s²). What horizontal force acts on the cup?`,
    options: [r`1.0 N of static friction, directed backward`, r`1.0 N of kinetic friction, directed forward`, r`5.0 N of static friction, directed forward`, r`1.0 N of static friction, directed forward`],
    correctAnswer: 3,
    explanation: r`The nurse pushes the cart, not the cup, so the only horizontal force on the cup is static friction from the cart top, and it must equal ma = (0.50)(2.0) = 1.0 N forward. A backward force would make the cup accelerate backward, kinetic friction would need slipping, and 5.0 N is the cup's weight, not the force its acceleration requires.`,
  },
  [r`Inertia is measured by {{c1::mass}} alone, momentum also requires {{c1::velocity}}, and force requires {{c1::acceleration}}.`]: {
    question: r`Compare a 2000 kg truck parked at a curb with a 0.010 kg bullet travelling at 400 m/s. Which statement is correct?`,
    options: [r`The truck has more inertia and also has more momentum`, r`The truck has more inertia; the bullet has more momentum`, r`The bullet has more inertia; the truck has more momentum`, r`The bullet has more inertia and also has more momentum`],
    correctAnswer: 1,
    explanation: r`Inertia is mass alone, so the truck has far more, but momentum is mass times velocity: zero for the parked truck and (0.010)(400) = 4 kg·m/s for the bullet. Giving the truck more momentum ignores that it is at rest, and giving the bullet more inertia confuses its speed with resistance to acceleration.`,
  },
  [r`A box is pressed horizontally against a wall hard enough to stay up. Which force supports its weight?`]: {
    question: r`A 2.0 kg book is held at rest against a vertical wall by a horizontal push of 50 N, with μs = 0.50 between book and wall (g = 10 m/s²). What friction force acts on the book?`,
    options: [r`25 N`, r`50 N`, r`20 N`, r`10 N`],
    correctAnswer: 2,
    explanation: r`The book is at rest, so upward static friction must equal its weight, mg = 20 N. The 25 N answer is the maximum available, μsN = (0.50)(50), which is more than is needed and so is not reached, 50 N is the push, which sets the normal force, and 10 N multiplies the coefficient by the weight.`,
  },
  [r`In skin traction the therapeutic force equals {{c1::the hanging weight}}, while the patient's body must supply {{c1::countertraction}}.`]: {
    question: r`In a traction setup, a single cord runs from a patient's leg over three ideal pulleys, each of which only changes the cord's direction, to a 4.0 kg mass hanging at rest (g = 10 m/s²). What force does the cord exert on the leg?`,
    options: [r`40 N`, r`120 N`, r`13 N`, r`4.0 N`],
    correctAnswer: 0,
    explanation: r`An ideal pulley only redirects the cord, so the tension everywhere equals the hanging weight, (4.0)(10) = 40 N, and that is the pull on the leg. The 120 N answer multiplies by the number of pulleys, 13 N divides by it, and 4.0 N reports the mass as if it were a force.`,
  },
  [r`A coefficient of friction is {{c1::dimensionless}}, so 0.4 is a plausible value but {{c1::0.4 N}} is not.`]: {
    question: r`A 20 N horizontal pull keeps a block that weighs 80 N sliding at constant velocity across a level bench. What is the coefficient of kinetic friction?`,
    options: [r`0.25, a pure number`, r`0.25 newtons`, r`4.0, a pure number`, r`4.0 newtons`],
    correctAnswer: 0,
    explanation: r`At constant velocity friction equals the 20 N pull, and μk = f/N = 20 N/80 N = 0.25 with the units cancelling. A coefficient is a ratio of two forces, so any answer in newtons is wrong, and 4.0 divides the normal force by the friction force, the ratio upside down.`,
  },
  [r`A crate sits unsecured in a truck bed. What accelerates it, and how hard can the truck accelerate before it slides?`]: {
    question: r`A 40 kg crate sits unsecured on a flatbed truck with μs = 0.30 between crate and bed (g = 10 m/s²). The driver brakes at 4.0 m/s². What does the crate do?`,
    options: [r`It slides toward the rear; friction allows only 3.0 m/s²`, r`It stays in place; friction allows as much as 12 m/s²`, r`It slides toward the cab; friction allows only 3.0 m/s²`, r`It stays in place; static friction always meets the need`],
    correctAnswer: 2,
    explanation: r`Static friction can give the crate at most μs g = 3.0 m/s², less than the truck's 4.0 m/s², so the crate cannot slow as fast as the bed and slides forward toward the cab. Sliding rearward is what happens when the truck speeds up, 12 m/s² multiplies by the mass, which actually cancels, and static friction is limited to μsN.`,
  },
  [r`A plot of net force versus acceleration for one object is a line through the origin with slope {{c1::the mass}}.`]: {
    question: r`In a lab, the net force on a cart is varied and its acceleration recorded. The plot of net force against acceleration is a straight line through the origin that passes through the point (4.0 m/s², 10 N). What is the cart's mass?`,
    options: [r`0.40 kg`, r`40 kg`, r`14 kg`, r`2.5 kg`],
    correctAnswer: 3,
    explanation: r`The slope of a force against acceleration plot is F/a = m, so m = 10/4.0 = 2.5 kg. The 0.40 kg answer inverts the slope, 40 kg multiplies the two coordinates, and 14 kg adds them.`,
  },
  [r`An orbiting astronaut is apparently weightless. How could you still measure her mass?`]: {
    question: r`A crew member on an orbiting station needs the mass of a tissue sample. Which method would work there?`,
    options: [r`Timing its oscillation on a spring of known stiffness`, r`Hanging it from a spring scale and reading the stretch`, r`Comparing it with known masses on a two-pan balance`, r`Setting it on an electronic scale fixed to the floor`],
    correctAnswer: 0,
    explanation: r`The period of a mass on a spring, T = 2π√(m/k), depends on inertia and contains no g, so it still gives the mass in free fall. A hanging spring scale, a pan balance and a floor scale all rely on the sample's weight pressing or pulling on something, and in orbit the sample and the instrument fall together, so each reads nothing.`,
  },
  [r`Why do knee ligaments experience forces several times body weight during a stiff-legged landing?`]: {
    question: r`A 60 kg gymnast lands moving downward at 6.0 m/s and stops over a distance of 0.30 m, with constant deceleration (g = 10 m/s²). What upward force does the ground exert on her while she stops?`,
    options: [r`3600 N`, r`4200 N`, r`3000 N`, r`600 N`],
    correctAnswer: 1,
    explanation: r`Her deceleration is v²/(2d) = 36/0.60 = 60 m/s², and the ground must both support her and stop her: F = m(g + a) = (60)(70) = 4200 N. The 3600 N answer is ma alone and forgets her weight, 3000 N subtracts the weight where it should add, and 600 N is only her weight, the force when standing still.`,
  },
  [r`At constant applied force, a plot of acceleration versus $1/m$ is a straight line whose slope is {{c1::the applied force}}.`]: {
    question: r`A constant force is applied to carts of different mass, and acceleration is plotted against 1/m. The straight line through the origin passes through the point (0.50 kg⁻¹, 6.0 m/s²). What is the applied force?`,
    options: [r`3.0 N`, r`6.0 N`, r`0.083 N`, r`12 N`],
    correctAnswer: 3,
    explanation: r`Since a = F(1/m), the slope is the force: 6.0/0.50 = 12 N. Equivalently, 1/m = 0.50 kg⁻¹ means a 2.0 kg cart accelerating at 6.0 m/s². The 3.0 N answer multiplies the two coordinates, 6.0 N treats 0.50 as if it were 1, and 0.083 N inverts the slope.`,
  },
  [r`Why is a lawnmower harder to push at a downward angle than to pull at an upward angle?`]: {
    question: r`A 15 kg mower is pushed across level grass by a 100 N force directed along its handle, 30° below the horizontal (sin 30° = 0.50). With a coefficient of friction of 0.20 and g = 10 m/s², what is the friction force?`,
    options: [r`40 N`, r`30 N`, r`20 N`, r`50 N`],
    correctAnswer: 0,
    explanation: r`The push has a downward component of (100)(0.50) = 50 N, so N = 150 + 50 = 200 N and f = (0.20)(200) = 40 N. The 30 N answer uses N = mg and ignores the push, 20 N subtracts the component as if the mower were pulled upward, and 50 N adds the whole 100 N to the weight.`,
  },
  [r`Joint reaction forces are typically {{c1::several times body weight}} because muscles act on {{c1::short lever arms}}.`]: {
    question: r`A person stands on the ball of one foot. The ground pushes up with 700 N at a point 15 cm in front of the ankle joint, and the Achilles tendon pulls up on the heel 5.0 cm behind the joint. Taking torques about the ankle, what is the tendon force?`,
    options: [r`233 N`, r`2100 N`, r`700 N`, r`3500 N`],
    correctAnswer: 1,
    explanation: r`Balancing torques about the ankle, T(5.0 cm) = (700 N)(15 cm), so T = 2100 N, three times body weight because the tendon's lever arm is short. The 233 N answer inverts the lever-arm ratio, 700 N assumes equal lever arms, and 3500 N multiplies the force by the 5.0 cm arm with no torque balance.`,
  },
  [r`Why does an occupant feel pressed back into the seat when a car accelerates?`]: {
    question: r`An 80 kg driver sits in a car that is accelerating forward at 3.0 m/s². Viewed from the ground, what horizontal force or forces act on the driver?`,
    options: [r`A 240 N backward force of inertia, and nothing else at all`, r`A 240 N forward push and a 240 N backward force that cancel`, r`No horizontal force, since the driver is at rest in the car`, r`A 240 N forward push from the seat back, and nothing else`],
    correctAnswer: 3,
    explanation: r`The driver accelerates forward at 3.0 m/s², so a net forward force of (80)(3.0) = 240 N must act, and the seat back supplies it. No backward force exists in the ground frame: the pressed-back feeling is inertia plus the seat's push. Cancelling forces or no force at all would mean zero acceleration, which is not what the ground observer sees.`,
  },
}
